specifications.definition:
fun given target =>
  have g := TaggedUrn.urnScore given;
  have t := TaggedUrn.urnScore target;
  if t ≤ g then (0, g - t) else (1, t - g)

fun candidate request =>
  have p := CapDAG.capScore candidate;
  have r := CapDAG.capScore request;
  if r ≤ p then (0, p - r) else (1, r - p)

claims.statement:
∀ (a : CapDAG.Run.Control.RunAsk),
  CapDAG.Run.Control.next CapDAG.Run.Control.RunPhase.ended a =
    { phase := CapDAG.Run.Control.RunPhase.ended, act := CapDAG.Run.Control.RunAct.none }
